def on_message(msg):
    h = msg.headers()        # {'seq-id': ..., 'pos': ..., 'size': ...}
    parts = buffers.setdefault(h['seq-id'], [None] * h['size'])
    parts[h['pos'] - 1] = msg.value()
    if all(p is not None for p in parts):
        deliver(b''.join(parts))
        buffers.pop(h['seq-id'])
